sys_script_fix.script:
gs.info('par_dashboards Update widgets to 48 columns. Start');
if(getDashboardCurrentVersion() == "1.1.1") {
	updateDashboardLayout();
}

gs.info('par_dashboards Update widgets to 48 columns. End');

function getDashboardCurrentVersion() {
    var versionGR = new GlideRecord("sys_store_app");
    versionGR.addQuery('scope', 'sn_dashboard');
    versionGR.query();
    if (versionGR.next()) {
        return versionGR.getValue('version');
    }
}

function updateDashboardLayout() {
    var gr = new GlideRecord("par_dashboard_widget");
    gr.query();
    var numWidgets = gr.getRowCount();
    var numWidgetsUpdated = 0;
    while (gr.next()) {
        gr.x = gr.x * 4;
        gr.w = gr.w * 4;
        var updated = gr.update();
        if (updated)
            numWidgetsUpdated++;
    }

    gs.info('updateDashboardLayout executed. Total widgets=[' + numWidgets + '], widgets updated=[' + numWidgetsUpdated + ']');
}
